function getRecordVenue(record) {
  if (isBookRecord(record)) return "";
  return String(
    record.venue_name ||
    record.venue ||
    record.source_name ||
    record.source ||
    record.host_venue ||
    record.host_venue_name ||
    record.primary_location?.source?.display_name ||
    "",
  ).trim();
}

function canonicalVenueTrack(record) {
  if (isBookRecord(record)) return "";
  if (String(record?.venue_type || "").trim().toLowerCase() !== "conference") return "";
  const track = String(record?.venue_track || "Main").trim();
  const key = track.toLowerCase().replace(/[_\s-]+/g, " ");
  return ({main:"Main", workshop:"Workshop", workshops:"Workshop", tutorial:"Tutorial", tutorials:"Tutorial",
    demo:"Demo", demos:"Demo", challenge:"Challenge", challenges:"Challenge", "short paper":"Short Paper",
    "short papers":"Short Paper", findings:"Findings", poster:"Poster", posters:"Poster", industry:"Industry",
    "doctoral consortium":"Doctoral Consortium", other:"Other", "main track":"Main", "workshop track":"Workshop",
    "industry track":"Industry", "demo track":"Demo", demonstration:"Demo", demonstrations:"Demo"})[key] || track;
}

function venueFilterValue(record) {
  if (isBookRecord(record)) return "__not_applicable__";
  return String(record.venue_id || "").trim() || (getRecordVenue(record)
    ? getRecordVenue(record).toLocaleLowerCase()
    : "__unknown__");
}

function venueBaseDisplayLabel(record) {
  const name = getRecordVenue(record);
  if (!name) return "Unknown publication venue";
  const acronym = String(record.venue_acronym || "").trim();
  return acronym ? `${name} (${acronym})` : name;
}

function venueDisplayLabel(record) {
  if (isBookRecord(record)) return "";
  const exported = String(record.venue_label || "").trim();
  if (exported) return exported;
  const name = getRecordVenue(record);
  if (!name) return "Unknown publication venue";
  const acronym = String(record.venue_acronym || "").trim();
  const track = canonicalVenueTrack(record);
  let label = name;
  if (acronym) label += ` (${acronym})`;
  const trackLabel = formatTask(track);
  const alreadyNamed = trackLabel && new RegExp(`\\b${trackLabel.replace(/s$/i, "")}s?\\b`, "i")
    .test(`${name} ${acronym}`);
  if (track && track !== "Main" && !alreadyNamed) label += ` · ${trackLabel}`;
  return label;
}

function recordVenueType(record) {
  return String(record.publication_type || record.venue_type || "").trim().toLocaleLowerCase();
}

function isFormallyPublished(paper) {
  const publicationType = String(paper?.publication_type || "").trim().toLocaleLowerCase();
  return publicationType === "conference" || publicationType === "journal"
    || publicationType === "book";
}

function isBookRecord(record) {
  return String(record?.publication_type || "").trim().toLocaleLowerCase() === "book";
}

function venueDisplayHtml(record) {
  const label = venueDisplayLabel(record);
  const type = recordVenueType(record);
  if (!label || !type) return escapeHtml(label);
  return `<span class="venue-type-badge">${escapeHtml(formatTask(type))}</span><span class="venue-label-name"> · ${escapeHtml(label)}</span>`;

function institutionPaperRowHtml(paper, markerEntry) {
  const publication = PaperDetailsHelpers.publicationMetadata(
    paper, venueDisplayLabel(paper), publicationYear(paper),
  );
  const metadata = [publication.venue, publication.year, getTasks(paper).map(formatPublicTask).join(" + ")]
    .filter(Boolean).map(escapeHtml).join(" · ");
  return `<li><button type="button" class="institution-paper-row" data-marker-paper="${escapeHtml(paperIdentity(paper))}" data-parent-marker="${escapeHtml(markerEntry.institutionKey)}"><span class="institution-paper-title">${paperTitleHtml(paper)}</span>${metadata ? `<span class="institution-paper-metadata">${metadata}</span>` : ""}</button></li>`;

function publicationMetadata(record, venueValue, yearValue) {
  const typeLabel = publicationTypeLabel(record?.publication_type);
  const rawVenue = String(venueValue || "").trim();
  // Only strip an explicitly delimited duplicate label. A venue beginning
  // with "Journal" or "Conference" may legitimately contain that word.
  const escapedType = typeLabel.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const duplicatePrefix = typeLabel
    ? new RegExp(`^${escapedType}\\s*(?:[:|–—-])\\s*`, "i")
    : null;
  const venue = duplicatePrefix ? rawVenue.replace(duplicatePrefix, "").trim() : rawVenue;
  const year = yearValue === null || yearValue === undefined
    ? ""
    : String(yearValue).trim();
  return { typeLabel, venue, year };

function updateVenueDimensionFilters(venueCounts, venueTypeCounts, allPapers) {
  const metadataByVenue = new Map();
  allPapers.filter((record) => !isBookRecord(record)).forEach((record) => {
    const value = venueFilterValue(record);
    const existing = metadataByVenue.get(value);
    const track = canonicalVenueTrack(record);
    if (existing) {
      if (track) existing.tracks.add(track);
      return;
    }
    metadataByVenue.set(value, {
      label: venueDisplayLabel(record),
      baseLabel: venueBaseDisplayLabel(record),
      name: getRecordVenue(record) || "Unknown publication venue",
      acronym: record.venue_acronym || "",
      track,
      tracks: new Set(track ? [track] : []),
      type: recordVenueType(record) || "__unknown__",
    });
  });
  metadataByVenue.forEach((metadata) => {
    if (metadata.tracks.size > 1) {
      metadata.label = `${metadata.baseLabel} — All Tracks`;
      metadata.track = "";
    }
  });
  includeZeroCountOptions(venueCounts, allPapers,
    (record) => isBookRecord(record) ? [] : [venueFilterValue(record)],
  );
  includeZeroCountOptions(venueTypeCounts, allPapers,
    (record) => [recordVenueType(record) || "__unknown__"],
  );
  replaceCountedFilterOptions(
    venueFilter,
    "All",
    sortedVenueCounts(venueCounts, metadataByVenue),
    (value) => metadataByVenue.get(value)?.label
      || (value === "__unknown__" ? "Unknown publication venue" : value),
  );
  replaceCountedFilterOptions(
    venueTypeFilter,
    "All",
    sortedVenueTypeCounts(venueTypeCounts),
    (value) => value === "__unknown__" ? "Unknown" : formatTask(value),
  );
  syncFilterDropdownForSelect(venueFilter);
  syncFilterDropdownForSelect(venueTypeFilter);
}

def test_workshop_is_track_not_public_type(self):
    self.assertNotIn("workshop", {paper.get("venue_type") for paper in self.papers})
    workshop_papers = [paper for paper in self.papers if paper.get("venue_track") == "Workshop"]
    self.assertTrue(workshop_papers)
    self.assertEqual({paper.get("venue_type") for paper in workshop_papers}, {"conference"})
    self.assertTrue(all(
        not label.startswith("Conference · ")
        and ("workshop" in label.casefold() or label.endswith(" · Workshop"))
        for label in (paper.get("venue_label", "") for paper in workshop_papers)
    ))

def test_multi_track_venue_options_use_all_tracks_without_changing_paper_labels(self):
    result = self.run_track_aggregated_venue_fixture()
    tracks_by_venue = {}
    metadata_by_venue = {}
    counts_by_venue = {}
    for paper in self.papers:
        venue_id = paper.get("venue_id")
        if not venue_id:
            continue
        track = paper.get("venue_track", "")
        if track:
            tracks_by_venue.setdefault(venue_id, set()).add(track)
        metadata_by_venue[venue_id] = (
            paper.get("venue_name", ""), paper.get("venue_acronym", ""),
        )
        counts_by_venue[venue_id] = counts_by_venue.get(venue_id, 0) + 1

    multi_track_venues = {
        venue_id for venue_id, tracks in tracks_by_venue.items() if len(tracks) > 1
    }
    self.assertGreater(len(multi_track_venues), 2)
    for venue_id in multi_track_venues:
        with self.subTest(venue_id=venue_id):
            name, acronym = metadata_by_venue[venue_id]
            base_label = f"{name} ({acronym})" if acronym else name
            self.assertEqual(
                result["options"][venue_id],
                f"{base_label} — All Tracks ({counts_by_venue[venue_id]})",
            )

